var prefabPath = "Assets/_Project/Prefabs/Players/Player_Invector.prefab";
var root = UnityEditor.PrefabUtility.LoadPrefabContents(prefabPath);
var sb = new System.Text.StringBuilder();
try {
  var volumes = root.GetComponentsInChildren<UnityEngine.Rendering.HighDefinition.CustomPassVolume>(true);
  sb.AppendLine("prefab CPVs=" + volumes.Length);
  foreach (var cpv in volumes) {
    bool hasScanner = false;
    foreach (var p in cpv.customPasses) if (p is Project.Rendering.ScannerHdrpCustomPass) hasScanner = true;
    if (!hasScanner) continue;
    cpv.enabled = false;
    // Fix serialized thickness on pass
    foreach (var p in cpv.customPasses) {
      if (p is Project.Rendering.ScannerHdrpCustomPass) {
        var so = new UnityEditor.SerializedObject(cpv);
        // edit via SerializedProperty on customPasses
      }
    }
    var soCpv = new UnityEditor.SerializedObject(cpv);
    var passes = soCpv.FindProperty("customPasses");
    if (passes == null) passes = soCpv.FindProperty("m_CustomPasses");
    // ManagedReference list may be under references - try iterate
    var iterator = soCpv.GetIterator();
    while (iterator.NextVisible(true)) {
      if (iterator.name == "lineThickness") iterator.floatValue = 2f;
      if (iterator.name == "enabled" && iterator.propertyPath.Contains("customPasses")) { /* leave pass enabled; volume gated */ }
    }
    soCpv.ApplyModifiedPropertiesWithoutUndo();

    var gate = cpv.GetComponent<Project.Rendering.ScannerHdrpOverlayGate>();
    if (gate == null) gate = cpv.gameObject.AddComponent<Project.Rendering.ScannerHdrpOverlayGate>();
    UnityEditor.EditorUtility.SetDirty(cpv);
    UnityEditor.EditorUtility.SetDirty(gate);
    sb.AppendLine("Updated CPV on " + cpv.gameObject.name + " enabled=" + cpv.enabled + " gate=" + (gate!=null));
  }
  UnityEditor.PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
  sb.AppendLine("prefab saved");
} finally {
  UnityEditor.PrefabUtility.UnloadPrefabContents(root);
}

